function renderCsv({ details = csvDetails, research = csvResearch, bump = csvBump } = {}) {
  return renderUnitBody({
    unit: { ...csvUnit, bumpIds: [bump.id] },
    bumps: [bump],
    details: { [bump.id]: details },
    fixed: ['GHSA-8cw4-87c7-c6xx'],
    partly: [],
    research: research ? { [bump.id]: research } : {},
    scope: 'consumer-facing',
    severity: 'moderate',
    ref: 'main',
    repoUrl,
    runUrl,
    now,
  })
}

function indexesInOrder({ body, parts }) {
  const indexes = parts.map((part) => body.indexOf(part))
  expect(
    indexes.every((index) => index >= 0),
    `missing part in: ${indexes}`,
  ).toBe(true)
  return indexes.every((index, i) => i === 0 || index > indexes[i - 1])
}

describe('renderUnitBody major', () => {
  it('should render the sections in order', () => {
    const body = renderCsv()

    expect(
      indexesInOrder({
        body,
        parts: [
          'This PR fixes 1 advisory (consumer-facing, moderate+).',
          '| Package | Change | Type | Age | Downloads/wk | Fixes | Affects |',
          `[\`5.6.0\` → \`7.0.2\`](${compareUrl})`,
          '**major**',
          '89 days',
          '3.7M',
          '[@payloadcms/plugin-import-export](https://github.com/payloadcms/payload/tree/main/packages/plugin-import-export)',
          '### csv-parse: Prototype replacement still reachable via columns path',
          '<summary>More information</summary>',
          '<summary>Breaking changes checked</summary>',
          '<summary>Release notes</summary>',
          '<summary>Commits</summary>',
          'Generated by audit-dependencies · [workflow run](' + runUrl + ')',
          '<!-- audit-deps:',
        ],
      }),
    ).toBe(true)
  })

  it('should end with exactly one marker', () => {
    const body = renderCsv()
    const lines = body.trimEnd().split('\n')

    expect(body.match(/<!-- audit-deps:/g)).toHaveLength(1)
    expect(lines.at(-1)).toMatch(/^<!-- audit-deps: /)
  })

  it('should link the GHSA with its short label in Fixes', () => {
    expect(renderCsv()).toContain(`moderate [8cw4](${ghsaUrl})`)
  })

  it('should render Codex change and usage', () => {
    const body = renderCsv()

    expect(body).toContain('6.0.0 renames relax')
    expect(body).toContain('We do not use relax.')
    expect(body).toContain('packages/plugin-import-export/src/parseCSV.ts')
  })

  it('should say Not checked. when research is missing', () => {
    expect(renderCsv({ research: null })).toContain('Not checked.')
  })

  it('should list commits and the remaining count', () => {
    const body = renderCsv()

    expect(body).toContain('[eb4d148](https://github.com/adaltas/node-csv/commit/eb4d148aaaaaaaa)')
    expect(body).toContain('11 more')
  })

  it('should render release links instead of commits when the repo moved', () => {
    const body = renderCsv({
      details: {
        ...csvDetails,
        commits: {
          commits: [],
          total: 0,
          compareUrl: null,
          repoMoved: true,
          releaseLinks: [
            'https://github.com/old/repo/releases',
            'https://github.com/new/repo/releases',
          ],
        },
      },
    })

    expect(body).toContain('https://github.com/old/repo/releases')
    expect(body).toContain('https://github.com/new/repo/releases')
  })
})

describe('draft handling', () => {
  const noNotes = {
    ...csvDetails,
    notes: {
      entries: [],
      links: { releases: null, changelog: null, compare: null },
      source: 'none',
    },
  }

  it('should put the draft banner first and start Codex text with the diff note', () => {
    const body = renderCsv({ details: noNotes })

    expect(body.startsWith('No release notes found for 7.x. Checked from the package diff;')).toBe(
      true,
    )
    expect(body).toContain('Checked from the package diff (no release notes)')
  })

  it('should mark a major with no notes as a draft unit', () => {
    expect(isDraftUnit({ unit: csvUnit, details: { 'csv-parse-7': noNotes } })).toBe(true)
  })

  it('should not draft a non-major with no notes', () => {
    const minor = { ...csvBump, id: 'x', isMajor: false, from: '^5.6.0', to: '5.7.0' }
    const unit = { id: 'non-major', kind: 'group', branch: 'b', bumpIds: ['x'] }
    const body = renderUnitBody({
      unit,
      bumps: [minor],
      details: { x: noNotes },
      fixed: [],
      partly: [],
      research: {},
      scope: 'consumer-facing',
      severity: 'moderate',
      ref: 'main',
      repoUrl,
      runUrl,
      now,
    })

    expect(isDraftUnit({ unit, details: { x: noNotes } })).toBe(false)
    expect(body).not.toContain('No release notes found for')
  })
})

const GHSA_DIGITS = '23456789'

function ghsaFor(index) {
  return `GHSA-cccc-ffff-${GHSA_DIGITS[(index >> 3) & 7]}${GHSA_DIGITS[index & 7]}cc`
}

describe('renderUnitBody group', () => {
  function makeBump(index) {
    return {
      id: `dep-${index}`,
      dependency: `dep-${index}`,
      from: '^1.0.0',
      fromVersion: '1.0.0',
      to: index % 2 === 0 ? '1.0.1' : '1.1.0',
      isMajor: false,
      manifests: ['package.json'],
      advisories: [ghsaFor(index)],
      fallbackFor: null,
    }
  }

  function makeDetails(index, { noteLength = 0 } = {}) {
    return {
      ...csvDetails,
      notes: {
        ...csvDetails.notes,
        entries: [
          {
            version: '1.0.1',
            url: 'https://x.test/n',
            text: 'n'.repeat(noteLength),
            isMajor: false,
          },
        ],
      },
      advisories: [
        {
          ghsa: ghsaFor(index),
          summary: `Summary ${index}`,
          description: 'd',
          severity: 'high',
          url: `https://github.com/advisories/${ghsaFor(index)}`,
        },
      ],
    }
  }

  function renderGroup({ count, noteLength = 0, partly = [], via = [] }) {
    const bumps = Array.from({ length: count }, (_, index) => makeBump(index))
    const details = Object.fromEntries(
      bumps.map((bump, index) => [
        bump.id,
        {
          ...makeDetails(index, { noteLength }),
          affects: { direct: csvDetails.affects.direct, via },
        },
      ]),
    )
    return {
      bumps,
      body: renderUnitBody({
        unit: {
          id: 'non-major',
          kind: 'group',
          branch: 'b',
          bumpIds: bumps.map((bump) => bump.id),
        },
        bumps,
        details,
        fixed: bumps.flatMap((bump) => bump.advisories),
        partly,
        research: {},
        scope: 'consumer-facing',
        severity: 'moderate',
        ref: 'main',
        repoUrl,
        runUrl,
        now,
      }),
    }
  }

  it('should render one row and one section set per bump', () => {
    const { body } = renderGroup({ count: 3 })

    expect(body.match(/^\| \[dep-\d/gm)).toHaveLength(3)
    expect(body.match(/<summary>Changes checked<\/summary>/g)).toHaveLength(3)
    expect(body.match(/^### dep-/gm)).toHaveLength(3)
    expect(body).not.toContain('Breaking changes checked')
  })

  it('should show minor and patch types', () => {
    const { body } = renderGroup({ count: 2 })

    expect(body).toContain('| patch |')
    expect(body).toContain('| minor |')
  })

  it('should list via packages when present', () => {
    const { body } = renderGroup({
      count: 1,
      via: [{ name: '@payloadcms/next', dir: 'next' }],
    })

    expect(body).toContain(
      'via: [@payloadcms/next](https://github.com/payloadcms/payload/tree/main/packages/next)',
    )
  })

  it('should render partly fixed advisories and the lead suffix', () => {
    const { body } = renderGroup({ count: 1, partly: [ghsaFor(0)] })

    expect(body).toContain('1 more is partly fixed.')
  })

  it('should stay under the body cap and keep the marker last', () => {
    const { body } = renderGroup({ count: 40, noteLength: 8000 })

    expect(body.length).toBeLessThanOrEqual(60000)
    expect(body.trimEnd().split('\n').at(-1)).toMatch(/^<!-- audit-deps: /)
    expect(body.match(/^\| \[dep-\d/gm)).toHaveLength(40)
    expect(body).toContain('Generated by audit-dependencies')
  })
})

